import pandas as pd
import numpy as np
import json
from scipy import stats as scipy_stats

df = pd.read_csv('/data/df.csv')

result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

try:
    sale_mask = (df['row_kind'] == 'sale') & (df['Currency'] == 'USD')
    df_sale = df[sale_mask].copy()

    cost_per_lb_by_mode = []
    modes = df_sale['Mode'].dropna().unique()
    for mode_val in modes:
        sub = df_sale[
            (df_sale['Mode'] == mode_val) &
            (df_sale['Weight'] > 0) &
            (df_sale['Weight UOM'].notna())
        ]
        total_cost = sub['Total Charge'].sum()
        total_weight = sub['Weight'].sum()
        if total_weight > 0:
            ratio = total_cost / total_weight
        else:
            ratio = float('nan')
        cost_per_lb_by_mode.append({"name": str(mode_val), "value": round(float(ratio), 6)})

    cost_per_lb_by_mode_sorted = sorted(
        [x for x in cost_per_lb_by_mode if not (x['value'] != x['value'])],
        key=lambda x: x['value'], reverse=True
    )

    result['segments'].append({
        "segment_column": "Mode",
        "metric_column": "Total Charge",
        "aggregation": "ratio",
        "label": "cost_per_lb",
        "results": cost_per_lb_by_mode_sorted
    })

    total_cost_all = df_sale.loc[
        (df_sale['Weight'] > 0) & (df_sale['Weight UOM'].notna()), 'Total Charge'
    ].sum()
    total_weight_all = df_sale.loc[
        (df_sale['Weight'] > 0) & (df_sale['Weight UOM'].notna()), 'Weight'
    ].sum()
    overall_cplb = total_cost_all / total_weight_all if total_weight_all > 0 else float('nan')

    result['segments'].append({
        "segment_column": "Mode",
        "metric_column": "Total Charge",
        "aggregation": "sum",
        "label": "total_charge_by_mode",
        "results": sorted(
            [{"name": str(m), "value": round(float(df_sale[df_sale['Mode'] == m]['Total Charge'].sum()), 4)}
             for m in modes],
            key=lambda x: x['value'], reverse=True
        )
    })

    result['segments'].append({
        "segment_column": "Mode",
        "metric_column": "Weight",
        "aggregation": "sum",
        "label": "total_weight_by_mode",
        "results": sorted(
            [{"name": str(m), "value": round(float(
                df_sale[(df_sale['Mode'] == m) & (df_sale['Weight'] > 0) & (df_sale['Weight UOM'].notna())]['Weight'].sum()
            ), 4)} for m in modes],
            key=lambda x: x['value'], reverse=True
        )
    })

    result['segments'].append({
        "segment_column": "Mode",
        "metric_column": "Weight",
        "aggregation": "count",
        "label": "shipment_count_by_mode",
        "results": sorted(
            [{"name": str(m), "value": int(df_sale[df_sale['Mode'] == m].shape[0])} for m in modes],
            key=lambda x: x['value'], reverse=True
        )
    })

    result['assumptions'].append(
        "cost_per_lb = Σ Total Charge / Σ Weight over sale+USD rows where Weight > 0 and Weight UOM is set; kg already converted to lb by cleaning."
    )
    result['assumptions'].append(
        f"Overall cost per lb across all modes: {overall_cplb:.4f} USD/lb."
    )
    result['assumptions'].append(
        "Cancelled (row_kind='cancelled') and non-USD rows excluded from all figures."
    )
except Exception as e:
    result['assumptions'].append(f"Segmentation error: {str(e)}")

